import {route} from './logic.mjs';
import {ANIMALS,STALLS} from './farm.mjs';
import {HOF} from './hof-layout.mjs';
// Animals use the barn's aisle and their own stalls; side-box occupancy blocks people only.
export function createFarmHousing(animals,colliders,height,horse,interactive){
 let state=null,lastTime=null;const motion=new Map();const ids=Object.keys(ANIMALS);function owns(id){return !!state?.alpLife.housed[id]||motion.has(id);}
 function pose(id,p){const model=animals.get(id);if(!model)return;const {g}=model;g.position.set(p.x,height(p.x,p.z),p.z);if(['goats','hens'].includes(id))g.children.forEach((o,i)=>o.position.set((i%2?1:-1)*.27,0,(i-1)*.25));g.rotation.y=id==='hens'?0:id==='berta'||id==='lotti'?-Math.PI/2:Math.PI/2;if(model.collider){model.collider.x=p.x;model.collider.z=p.z;}const q=id==='hens'?{x:16.8,z:1}:{x:HOF.barn.x,z:p.z};if(model.point){model.point.x=q.x;model.point.z=q.z;}const n=interactive.find(n=>id==='jonny'?n.id==='horse':n.animal===id);if(n){n.x=q.x;n.z=q.z;}}
 function corridors(id){const model=animals.get(id);const c=colliders.filter(c=>c!==model?.collider&&!c.animalStallArea&&!(id==='hens'&&c.x===HOF.coop.x&&c.z===HOF.coop.z));c.bounds=colliders.bounds;return c;}
 function sync(s){const first=!state;state=s;for(const id of ids){const wanted=s.alpLife.housed[id],model=animals.get(id);if(first){model.g.userData.housed=wanted;if(wanted)pose(id,STALLS[id]);continue;}const previous=model.g.userData.housed??false;if(wanted===previous)continue;model.g.userData.housed=wanted;const def=ANIMALS[id],start=motion.get(id)?.point|| (['hens','goats'].includes(id)&&!previous?{x:def.x,z:def.z}:{x:model.g.position.x,z:model.g.position.z});const goal=wanted?STALLS[id]:def,c= corridors(id),aisle={x:HOF.barn.x,z:start.z},entry=HOF.barn.entry;let way=[];
 if(id==='hens')way=route(start,wanted?{x:16.8,z:1}:def,c);else if(wanted){way=route(start,entry,c);way.push({x:1.5,z:goal.z},{x:goal.x,z:goal.z});}else{const inBarn=Math.abs(start.x-HOF.barn.x)<3.3&&Math.abs(start.z-HOF.barn.z)<3.5;way=inBarn?[aisle,entry,...route(entry,def,c)]:route(start,def,c);}
 if(!way.length)way=[{x:goal.x,z:goal.z}];motion.set(id,{point:{...start},way,wanted});}}
 function step(t){const dt=lastTime===null?0:Math.min(.05,Math.max(0,t-lastTime));lastTime=t;if(!state)return;for(const id of ids){const model=animals.get(id),wanted=state.alpLife.housed[id];if(!motion.has(id)){if(wanted){pose(id,STALLS[id]);model.g.userData.housed=true;}continue;}const m=motion.get(id),next=m.way[0];if(!next){motion.delete(id);if(wanted)pose(id,STALLS[id]);else{if(['goats','hens'].includes(id))model.g.position.set(0,0,0);if(model.point){model.point.x=ANIMALS[id].x+(id==='hens'?0:1.6);model.point.z=ANIMALS[id].z+1;}const n=interactive.find(n=>id==='jonny'?n.id==='horse':n.animal===id);if(n){n.x=id==='jonny'?6:model.point.x;n.z=id==='jonny'?3:model.point.z;}}continue;}const dx=next.x-m.point.x,dz=next.z-m.point.z,d=Math.hypot(dx,dz),stride=Math.min(d,dt*(id==='hens'?1.6:1.8));if(d<.025){m.way.shift();continue;}m.point.x+=dx/d*stride;m.point.z+=dz/d*stride;pose(id,m.point);model.g.rotation.y=Math.atan2(dx,dz);if(id==='hens'&&wanted&&m.way.length===1&&d<.1){m.point={...STALLS.hens};m.way=[];}model.g.userData.walkingToShelter=true;model.legs?.forEach((leg,i)=>leg.rotation.x=Math.sin(t*5+i*Math.PI)*.24);}}
 return{owns,sync,step,motion};
}
